{"sql": "SELECT r.name, SUM(o.amount_inr) AS revenue FROM regions r JOIN customers c ON r.region_id = c.region_id JOIN orders o ON c.customer_id = o.customer_id WHERE o.status = 'delivered' AND strftime('%Y', o.order_date) = '2026' AND strftime('%m', o.order_date) BETWEEN '07' AND '09' GROUP BY r.name"}
